arguments.cmd:
mkdir -p /app/output && cat > /app/output/index.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <meta name="description" content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=Plus+Jakarta+Sans:wght@700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --black: #050505;
      --ink: #17151f;
      --muted: #696372;
      --line: rgba(15, 14, 20, 0.11);
      --purple: #7638FA;
      --orange: #FF7A00;
      --magenta: #ef2bad;
      --cream: #fff8ef;
      --soft: #f7f3ff;
      --blue-soft: #eef8ff;
      --green-soft: #effbf3;
      --white: #ffffff;
      --shadow: 0 24px 70px rgba(55, 31, 108, 0.14);
      --radius-xl: 34px;
      --radius-lg: 24px;
      --radius-md: 18px;
      --max: 1180px;
    }

    * { box-sizing: border-box; }

    html {
      scroll-behavior: smooth;
      -webkit-text-size-adjust: 100%;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--ink);
      background:
        radial-gradient(circle at top left, rgba(118, 56, 250, 0.14), transparent 31rem),
        radial-gradient(circle at 88% 12%, rgba(255, 122, 0, 0.16), transparent 26rem),
        linear-gradient(180deg, #fff 0%, #fffaf5 42%, #fff 100%);
      min-height: 100vh;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }

    button, a { -webkit-tap-highlight-color: transparent; }

    .site-shell {
      width: min(var(--max), calc(100% - 40px));
      margin: 0 auto;
    }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 50;
      backdrop-filter: blur(18px);
      background: rgba(255, 255, 255, 0.78);
      border-bottom: 1px solid rgba(255, 255, 255, 0.55);
    }

    .nav {
      min-height: 78px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-weight: 800;
      font-size: 1.3rem;
      letter-spacing: -0.04em;
    }

    .brand-mark {
      width: 38px;
      height: 38px;
      border-radius: 13px;
      display: grid;
      place-items: center;
      color: #fff;
      background: conic-gradient(from 210deg, var(--orange), var(--magenta), var(--purple), var(--orange));
      box-shadow: 0 10px 24px rgba(118, 56, 250, 0.26);
      position: relative;
    }

    .brand-mark::before {
      content: "";
      width: 17px;
      height: 17px;
      border: 3px solid currentColor;
      border-radius: 7px;
      display: block;
    }

    .brand-mark::after {
      content: "";
      width: 5px;
      height: 5px;
      background: currentColor;
      border-radius: 50%;
      position: absolute;
      right: 10px;
      top: 10px;
    }

    .desktop-links {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 7px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.6);
    }

    .desktop-links a {
      padding: 10px 15px;
      color: #37313f;
      font-size: 0.93rem;
      font-weight: 700;
      border-radius: 999px;
      transition: background 180ms ease, color 180ms ease, transform 180ms ease;
    }

    .desktop-links a:hover {
      background: var(--black);
      color: #fff;
      transform: translateY(-1px);
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .login-btn,
    .primary-btn,
    .store-btn,
    .pill-link {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 9px;
      font-weight: 800;
      border-radius: 999px;
      transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
    }

    .login-btn {
      padding: 12px 20px;
      background: var(--black);
      color: white;
      box-shadow: 0 14px 26px rgba(0, 0, 0, 0.14);
    }

    .login-btn:hover,
    .primary-btn:hover,
    .store-btn:hover,
    .pill-link:hover { transform: translateY(-2px); }

    .menu-toggle {
      display: none;
      width: 46px;
      height: 46px;
      border: 1px solid var(--line);
      border-radius: 16px;
      background: #fff;
      cursor: pointer;
      position: relative;
    }

    .menu-toggle span,
    .menu-toggle::before,
    .menu-toggle::after {
      content: "";
      position: absolute;
      left: 13px;
      right: 13px;
      height: 2px;
      border-radius: 2px;
      background: var(--black);
      transition: transform 180ms ease, opacity 180ms ease, top 180ms ease;
    }

    .menu-toggle::before { top: 15px; }
    .menu-toggle span { top: 22px; }
    .menu-toggle::after { top: 29px; }
    .menu-toggle[aria-expanded="true"]::before { top: 22px; transform: rotate(45deg); }
    .menu-toggle[aria-expanded="true"] span { opacity: 0; }
    .menu-toggle[aria-expanded="true"]::after { top: 22px; transform: rotate(-45deg); }

    .mobile-panel {
      display: none;
      padding: 0 0 18px;
    }

    .mobile-panel.is-open { display: block; }

    .mobile-links {
      display: grid;
      gap: 8px;
      padding: 14px;
      background: rgba(255, 255, 255, 0.92);
      border: 1px solid var(--line);
      border-radius: 24px;
      box-shadow: var(--shadow);
    }

    .mobile-links a {
      padding: 15px 16px;
      border-radius: 16px;
      background: #fbf9ff;
      font-weight: 800;
    }

    .hero {
      padding: 76px 0 54px;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.02fr) minmax(320px, 0.78fr);
      align-items: center;
      gap: 46px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 13px;
      border-radius: 999px;
      color: #4d237b;
      background: rgba(118, 56, 250, 0.1);
      border: 1px solid rgba(118, 56, 250, 0.16);
      font-size: 0.82rem;
      font-weight: 900;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .hero h1 {
      margin: 22px 0 18px;
      max-width: 790px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(3.1rem, 7.4vw, 7.9rem);
      line-height: 0.91;
      letter-spacing: -0.085em;
      color: #07050c;
    }

    .gradient-text {
      background: linear-gradient(100deg, var(--purple), var(--magenta) 48%, var(--orange));
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }

    .hero p {
      max-width: 660px;
      margin: 0 0 28px;
      color: #4c4656;
      font-size: clamp(1.05rem, 1.7vw, 1.3rem);
      line-height: 1.65;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 15px;
    }

    .primary-btn {
      min-height: 58px;
      padding: 0 26px;
      color: #fff;
      background: linear-gradient(100deg, var(--black), #251445 56%, var(--purple));
      box-shadow: 0 20px 42px rgba(118, 56, 250, 0.24);
    }

    .trust-note {
      color: var(--muted);
      font-weight: 700;
      font-size: 0.95rem;
    }

    .hero-visual {
      min-height: 580px;
      position: relative;
      border-radius: 42px;
      background:
        linear-gradient(150deg, rgba(255, 255, 255, 0.44), rgba(255,255,255,0.12)),
        radial-gradient(circle at 20% 18%, #ffe49b, transparent 28%),
        radial-gradient(circle at 75% 22%, #ff75ca, transparent 30%),
        radial-gradient(circle at 50% 78%, #7638fa, transparent 38%),
        linear-gradient(145deg, #ff7a00, #ef2bad 45%, #7638fa);
      box-shadow: 0 34px 90px rgba(118, 56, 250, 0.24);
      overflow: hidden;
    }

    .phone-card {
      position: absolute;
      left: 50%;
      top: 51%;
      width: min(270px, 70%);
      height: 470px;
      transform: translate(-50%, -50%) rotate(4deg);
      border: 10px solid #151019;
      border-radius: 42px;
      background: #fff;
      box-shadow: 0 30px 70px rgba(19, 9, 34, 0.3);
      overflow: hidden;
    }

    .phone-notch {
      width: 92px;
      height: 22px;
      margin: 11px auto 0;
      background: #151019;
      border-radius: 0 0 14px 14px;
    }

    .story-top {
      display: flex;
      gap: 8px;
      padding: 17px 15px 12px;
    }

    .story-dot {
      flex: 1;
      height: 56px;
      border-radius: 20px;
      background: linear-gradient(135deg, #ffe7d0, #ff58b8 52%, #7638fa);
    }

    .phone-feed {
      margin: 0 15px;
      height: 292px;
      border-radius: 28px;
      background:
        linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.38) 100%),
        radial-gradient(circle at 70% 25%, #fff0a8, transparent 17%),
        linear-gradient(140deg, #7638fa, #ef2bad 48%, #ff7a00);
      position: relative;
      overflow: hidden;
    }

    .phone-feed::before,
    .phone-feed::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: rgba(255,255,255,0.82);
    }

    .phone-feed::before {
      width: 118px;
      height: 12px;
      left: 18px;
      bottom: 52px;
    }

    .phone-feed::after {
      width: 76px;
      height: 12px;
      left: 18px;
      bottom: 30px;
      opacity: 0.74;
    }

    .reaction-float,
    .creator-float,
    .safety-float {
      position: absolute;
      border-radius: 24px;
      background: rgba(255,255,255,0.9);
      backdrop-filter: blur(12px);
      border: 1px solid rgba(255,255,255,0.5);
      box-shadow: 0 22px 50px rgba(24, 10, 45, 0.18);
      font-weight: 900;
    }

    .reaction-float {
      right: 20px;
      top: 70px;
      padding: 15px 17px;
      transform: rotate(8deg);
    }

    .creator-float {
      left: 18px;
      bottom: 88px;
      padding: 16px 18px;
      transform: rotate(-6deg);
    }

    .safety-float {
      right: 25px;
      bottom: 35px;
      padding: 14px 17px;
      color: #295839;
      background: rgba(239, 251, 243, 0.91);
    }

    section { scroll-margin-top: 100px; }

    .section-pad { padding: 72px 0; }

    .feature-card,
    .split-card,
    .download-card {
      border: 1px solid rgba(14, 10, 22, 0.08);
      box-shadow: var(--shadow);
    }

    .feature-card {
      min-height: 480px;
      border-radius: var(--radius-xl);
      padding: clamp(28px, 5vw, 58px);
      background:
        radial-gradient(circle at 85% 20%, rgba(255, 122, 0, 0.22), transparent 28%),
        radial-gradient(circle at 15% 84%, rgba(118, 56, 250, 0.18), transparent 28%),
        #fff;
      display: grid;
      grid-template-columns: minmax(0, 0.95fr) minmax(280px, 0.8fr);
      gap: 36px;
      align-items: center;
      overflow: hidden;
    }

    .section-kicker {
      margin: 0 0 14px;
      color: var(--purple);
      font-size: 0.82rem;
      font-weight: 900;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .section-title {
      margin: 0;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(2.2rem, 5vw, 5.2rem);
      line-height: 0.98;
      letter-spacing: -0.07em;
      color: #08060d;
    }

    .section-copy {
      margin: 22px 0 0;
      color: #575160;
      font-size: 1.06rem;
      line-height: 1.75;
      max-width: 650px;
    }

    .pill-link {
      width: fit-content;
      margin-top: 28px;
      padding: 13px 18px;
      background: #111;
      color: #fff;
    }

    .feature-mosaic {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
      transform: rotate(2deg);
    }

    .mini-tile {
      min-height: 150px;
      border-radius: 28px;
      padding: 18px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      color: #fff;
      font-weight: 900;
      box-shadow: 0 16px 30px rgba(29, 16, 52, 0.13);
    }

    .mini-tile:nth-child(1) { background: linear-gradient(135deg, var(--purple), #bd47ff); }
    .mini-tile:nth-child(2) { background: linear-gradient(135deg, #ff7a00, #ffbd58); color: #221100; }
    .mini-tile:nth-child(3) { background: linear-gradient(135deg, #17151f, #3e2a6e); }
    .mini-tile:nth-child(4) { background: linear-gradient(135deg, #ef2bad, #ff7aab); }

    .tile-icon { font-size: 2rem; }

    .split-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 24px;
    }

    .split-card {
      position: relative;
      min-height: 520px;
      border-radius: var(--radius-xl);
      padding: clamp(28px, 4vw, 48px);
      overflow: hidden;
    }

    .split-card.safety {
      background:
        radial-gradient(circle at 85% 22%, rgba(87, 184, 116, 0.28), transparent 29%),
        radial-gradient(circle at 18% 82%, rgba(118, 56, 250, 0.1), transparent 28%),
        var(--green-soft);
    }

    .split-card.creators {
      background:
        radial-gradient(circle at 88% 20%, rgba(255, 122, 0, 0.36), transparent 30%),
        radial-gradient(circle at 18% 88%, rgba(239, 43, 173, 0.2), transparent 32%),
        #fff0f8;
    }

    .card-graphic {
      position: absolute;
      left: 36px;
      right: 36px;
      bottom: 30px;
      height: 150px;
      border-radius: 34px;
      background: rgba(255,255,255,0.74);
      border: 1px solid rgba(255,255,255,0.8);
      box-shadow: 0 18px 42px rgba(31, 21, 49, 0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 14px;
    }

    .badge-bubble {
      width: 72px;
      height: 72px;
      border-radius: 26px;
      display: grid;
      place-items: center;
      font-size: 2rem;
      background: #fff;
      box-shadow: 0 14px 24px rgba(22, 14, 39, 0.1);
    }

    .banner {
      padding: 32px 0 88px;
    }

    .banner-panel {
      min-height: 310px;
      display: grid;
      place-items: center;
      text-align: center;
      border-radius: 46px;
      color: #fff;
      padding: 36px;
      background:
        radial-gradient(circle at 18% 25%, rgba(255,255,255,0.4), transparent 18%),
        radial-gradient(circle at 82% 35%, rgba(255,255,255,0.22), transparent 22%),
        linear-gradient(115deg, #7638fa, #ef2bad 54%, #ff7a00);
      box-shadow: 0 28px 82px rgba(118, 56, 250, 0.28);
      overflow: hidden;
      position: relative;
    }

    .banner-panel::before,
    .banner-panel::after {
      content: "";
      position: absolute;
      width: 180px;
      height: 180px;
      border-radius: 48px;
      border: 2px solid rgba(255,255,255,0.36);
      transform: rotate(18deg);
    }

    .banner-panel::before { left: -55px; top: -42px; }
    .banner-panel::after { right: -45px; bottom: -70px; }

    .banner h2 {
      position: relative;
      z-index: 1;
      margin: 0;
      max-width: 860px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(2.5rem, 7vw, 6.7rem);
      line-height: 0.95;
      letter-spacing: -0.08em;
    }

    .news-head {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 24px;
      margin-bottom: 24px;
    }

    .view-more {
      flex: 0 0 auto;
      font-weight: 900;
      color: var(--purple);
      padding: 11px 0;
    }

    .carousel-wrap { position: relative; }

    .news-carousel {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(290px, 390px);
      gap: 18px;
      overflow-x: auto;
      overscroll-behavior-inline: contain;
      scroll-snap-type: inline mandatory;
      scroll-padding-inline: max(20px, calc((100vw - var(--max)) / 2));
      padding: 4px max(20px, calc((100vw - var(--max)) / 2)) 28px;
      margin-inline: calc(max(20px, calc((100vw - var(--max)) / 2)) * -1);
      -webkit-overflow-scrolling: touch;
      scrollbar-width: thin;
      scrollbar-color: rgba(118, 56, 250, 0.55) rgba(118, 56, 250, 0.08);
    }

    .news-carousel::-webkit-scrollbar { height: 10px; }
    .news-carousel::-webkit-scrollbar-track { background: rgba(118, 56, 250, 0.08); border-radius: 999px; }
    .news-carousel::-webkit-scrollbar-thumb { background: linear-gradient(90deg, var(--purple), var(--magenta), var(--orange)); border-radius: 999px; }

    .news-card {
      scroll-snap-align: start;
      min-height: 478px;
      border-radius: 30px;
      background: #fff;
      border: 1px solid rgba(14, 10, 22, 0.08);
      box-shadow: 0 18px 48px rgba(37, 20, 68, 0.1);
      overflow: hidden;
      transition: transform 180ms ease, box-shadow 180ms ease;
    }

    .news-card:hover {
      transform: translateY(-5px);
      box-shadow: 0 26px 62px rgba(37, 20, 68, 0.16);
    }

    .thumb {
      height: 210px;
      position: relative;
      overflow: hidden;
      background: var(--thumb-bg);
    }

    .thumb::before {
      content: "";
      position: absolute;
      inset: 22px;
      border-radius: 28px;
      background: rgba(255, 255, 255, 0.25);
      border: 1px solid rgba(255, 255, 255, 0.36);
      transform: rotate(var(--tilt));
    }

    .thumb::after {
      content: attr(data-icon);
      position: absolute;
      inset: 0;
      display: grid;
      place-items: center;
      font-size: 4.4rem;
      filter: drop-shadow(0 14px 24px rgba(0,0,0,0.14));
    }

    .news-body { padding: 22px; }

    .tags {
      display: flex;
      flex-wrap: wrap;
      gap: 7px;
      min-height: 31px;
      margin-bottom: 18px;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      min-height: 28px;
      padding: 0 9px;
      border-radius: 999px;
      background: #f2ecff;
      color: #5b22cd;
      font-size: 0.72rem;
      font-weight: 900;
      letter-spacing: 0.035em;
    }

    .news-card h3 {
      margin: 0;
      color: #100d17;
      font-size: clamp(1.18rem, 2vw, 1.55rem);
      line-height: 1.16;
      letter-spacing: -0.04em;
    }

    .date {
      margin: 22px 0 0;
      color: var(--muted);
      font-weight: 800;
      font-size: 0.93rem;
    }

    .carousel-controls {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      margin-top: 2px;
    }

    .scroll-btn {
      width: 48px;
      height: 48px;
      border: 1px solid var(--line);
      border-radius: 16px;
      background: #fff;
      color: var(--black);
      font-size: 1.35rem;
      font-weight: 900;
      cursor: pointer;
      box-shadow: 0 12px 28px rgba(37, 20, 68, 0.08);
    }

    .download { padding: 72px 0 84px; }

    .download-card {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      border-radius: 38px;
      padding: clamp(28px, 5vw, 54px);
      background:
        radial-gradient(circle at 92% 10%, rgba(255, 122, 0, 0.18), transparent 23%),
        #101015;
      color: white;
    }

    .download h2 {
      margin: 0 0 8px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(2.2rem, 5vw, 5rem);
      line-height: 0.98;
      letter-spacing: -0.07em;
    }

    .download p {
      margin: 0;
      color: rgba(255,255,255,0.72);
      font-size: 1.15rem;
      font-weight: 800;
    }

    .store-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
    }

    .store-btn {
      min-width: 150px;
      min-height: 54px;
      padding: 0 18px;
      color: #111;
      background: #fff;
    }

    .store-btn.alt {
      color: #fff;
      background: linear-gradient(100deg, var(--purple), var(--magenta));
    }

    .footer {
      padding: 58px 0 32px;
      background: #f7f4fb;
      border-top: 1px solid rgba(14, 10, 22, 0.08);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.3fr repeat(5, minmax(120px, 1fr));
      gap: 30px;
    }

    .footer-brand p {
      max-width: 270px;
      margin: 15px 0 0;
      color: var(--muted);
      line-height: 1.6;
      font-weight: 600;
    }

    .footer-col h3 {
      margin: 0 0 14px;
      font-size: 0.86rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .footer-col ul {
      list-style: none;
      margin: 0;
      padding: 0;
      display: grid;
      gap: 10px;
    }

    .footer-col a {
      color: #56505f;
      font-size: 0.94rem;
      font-weight: 700;
    }

    .footer-col a:hover { color: var(--purple); }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 22px;
      flex-wrap: wrap;
      margin-top: 48px;
      padding-top: 24px;
      border-top: 1px solid rgba(14, 10, 22, 0.1);
      color: #56505f;
