      padding: 0 0 18px;
    }

    .mobile-panel.is-open { display: block; }

    .mobile-links {
      display: grid;
      gap: 8px;
      padding: 14px;
      background: rgba(255, 255, 255, 0.92);
      border: 1px solid var(--line);
      border-radius: 24px;
      box-shadow: var(--shadow);
    }

    .mobile-links a {
      padding: 15px 16px;
      border-radius: 16px;
      background: #fbf9ff;
      font-weight: 800;
    }

    .hero {
      padding: 76px 0 54px;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.02fr) minmax(320px, 0.78fr);
      align-items: center;
      gap: 46px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 13px;
      border-radius: 999px;
      color: #4d237b;
      background: rgba(118, 56, 250, 0.1);
      border: 1px solid rgba(118, 56, 250, 0.16);
      font-size: 0.82rem;
      font-weight: 900;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .hero h1 {
      margin: 22px 0 18px;
      max-width: 790px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(3.1rem, 7.4vw, 7.9rem);
      line-height: 0.91;
      letter-spacing: -0.085em;
      color: #07050c;
    }

    .gradient-text {
      background: linear-gradient(100deg, var(--purple), var(--magenta) 48%, var(--orange));
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }

    .hero p {
      max-width: 660px;
      margin: 0 0 28px;
      color: #4c4656;
      font-size: clamp(1.05rem, 1.7vw, 1.3rem);
      line-height: 1.65;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 15px;
    }

    .primary-btn {
      min-height: 58px;
      padding: 0 26px;
      color: #fff;
      background: linear-gradient(100deg, var(--black), #251445 56%, var(--purple));
      box-shadow: 0 20px 42px rgba(118, 56, 250, 0.24);
    }

    .trust-note {
      color: var(--muted);
      font-weight: 700;
      font-size: 0.95rem;
    }

    .hero-visual {
      min-height: 580px;
      position: relative;
      border-radius: 42px;
      background:
        linear-gradient(150deg, rgba(255, 255, 255, 0.44), rgba(255,255,255,0.12)),
        radial-gradient(circle at 20% 18%, #ffe49b, transparent 28%),
        radial-gradient(circle at 75% 22%, #ff75ca, transparent 30%),
        radial-gradient(circle at 50% 78%, #7638fa, transparent 38%),
        linear-gradient(145deg, #ff7a00, #ef2bad 45%, #7638fa);
      box-shadow: 0 34px 90px rgba(118, 56, 250, 0.24);
      overflow: hidden;
    }

    .phone-card {
      position: absolute;
      left: 50%;
      top: 51%;
      width: min(270px, 70%);
      height: 470px;
      transform: translate(-50%, -50%) rotate(4deg);
      border: 10px solid #151019;
      border-radius: 42px;
      background: #fff;
      box-shadow: 0 30px 70px rgba(19, 9, 34, 0.3);
      overflow: hidden;
    }

    .phone-notch {
      width: 92px;
      height: 22px;
      margin: 11px auto 0;
      background: #151019;
      border-radius: 0 0 14px 14px;
    }

    .story-top {
      display: flex;
      gap: 8px;
      padding: 17px 15px 12px;
    }

    .story-dot {
      flex: 1;
      height: 56px;
      border-radius: 20px;
      background: linear-gradient(135deg, #ffe7d0, #ff58b8 52%, #7638fa);
    }

    .phone-feed {
      margin: 0 15px;
      height: 292px;
      border-radius: 28px;
      background:
        linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.38) 100%),
        radial-gradient(circle at 70% 25%, #fff0a8, transparent 17%),
        linear-gradient(140deg, #7638fa, #ef2bad 48%, #ff7a00);
      position: relative;
      overflow: hidden;
    }

    .phone-feed::before,
    .phone-feed::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: rgba(255,255,255,0.82);
    }

    .phone-feed::before {
      width: 118px;
      height: 12px;
      left: 18px;
      bottom: 52px;
    }

    .phone-feed::after {
      width: 76px;
      height: 12px;
      left: 18px;
      bottom: 30px;
      opacity: 0.74;
    }

    .reaction-float,
    .creator-float,
    .safety-float {
      position: absolute;
      border-radius: 24px;
      background: rgba(255,255,255,0.9);
      backdrop-filter: blur(12px);
      border: 1px solid rgba(255,255,255,0.5);
      box-shadow: 0 22px 50px rgba(24, 10, 45, 0.18);
      font-weight: 900;
    }

    .reaction-float {
      right: 20px;
      top: 70px;
      padding: 15px 17px;
      transform: rotate(8deg);
    }

    .creator-float {
      left: 18px;
      bottom: 88px;
      padding: 16px 18px;
      transform: rotate(-6deg);
    }

    .safety-float {
      right: 25px;
      bottom: 35px;
      padding: 14px 17px;
      color: #295839;
      background: rgba(239, 251, 243, 0.91);
    }

    section { scroll-margin-top: 100px; }

    .section-pad { padding: 72px 0; }

    .feature-card,
    .split-card,
    .download-card {
      border: 1px solid rgba(14, 10, 22, 0.08);
      box-shadow: var(--shadow);
    }

    .feature-card {
      min-height: 480px;
      border-radius: var(--radius-xl);
      padding: clamp(28px, 5vw, 58px);
      background:
        radial-gradient(circle at 85% 20%, rgba(255, 122, 0, 0.22), transparent 28%),
        radial-gradient(circle at 15% 84%, rgba(118, 56, 250, 0.18), transparent 28%),
        #fff;
      display: grid;
      grid-template-columns: minmax(0, 0.95fr) minmax(280px, 0.8fr);
      gap: 36px;
      align-items: center;
      overflow: hidden;
    }

    .section-kicker {
      margin: 0 0 14px;
      color: var(--purple);
      font-size: 0.82rem;
      font-weight: 900;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .section-title {
      margin: 0;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(2.2rem, 5vw, 5.2rem);
      line-height: 0.98;
      letter-spacing: -0.07em;
      color: #08060d;
    }

    .section-copy {
      margin: 22px 0 0;
      color: #575160;
      font-size: 1.06rem;
      line-height: 1.75;
      max-width: 650px;
    }

    .pill-link {
      width: fit-content;
      margin-top: 28px;
      padding: 13px 18px;
      background: #111;
      color: #fff;
    }

    .feature-mosaic {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
      transform: rotate(2deg);
    }

    .mini-tile {
      min-height: 150px;
      border-radius: 28px;
      padding: 18px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      color: #fff;
      font-weight: 900;
      box-shadow: 0 16px 30px rgba(29, 16, 52, 0.13);
    }

    .mini-tile:nth-child(1) { background: linear-gradient(135deg, var(--purple), #bd47ff); }
    .mini-tile:nth-child(2) { background: linear-gradient(135deg, #ff7a00, #ffbd58); color: #221100; }
    .mini-tile:nth-child(3) { background: linear-gradient(135deg, #17151f, #3e2a6e); }
    .mini-tile:nth-child(4) { background: linear-gradient(135deg, #ef2bad, #ff7aab); }

    .tile-icon { font-size: 2rem; }

    .split-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 24px;
    }

    .split-card {
      position: relative;
      min-height: 520px;
      border-radius: var(--radius-xl);
      padding: clamp(28px, 4vw, 48px);
      overflow: hidden;
    }

    .split-card.safety {
      background:
        radial-gradient(circle at 85% 22%, rgba(87, 184, 116, 0.28), transparent 29%),
        radial-gradient(circle at 18% 82%, rgba(118, 56, 250, 0.1), transparent 28%),
        var(--green-soft);
    }

    .split-card.creators {
      background:
        radial-gradient(circle at 88% 20%, rgba(255, 122, 0, 0.36), transparent 30%),
        radial-gradient(circle at 18% 88%, rgba(239, 43, 173, 0.2), transparent 32%),
        #fff0f8;
    }

    .card-graphic {
      position: absolute;
      left: 36px;
      right: 36px;
      bottom: 30px;
      height: 150px;
      border-radius: 34px;
      background: rgba(255,255,255,0.74);
      border: 1px solid rgba(255,255,255,0.8);
      box-shadow: 0 18px 42px rgba(31, 21, 49, 0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 14px;
    }

    .badge-bubble {
      width: 72px;
      height: 72px;
      border-radius: 26px;
      display: grid;
      place-items: center;
      font-size: 2rem;
      background: #fff;
      box-shadow: 0 14px 24px rgba(22, 14, 39, 0.1);
    }

    .banner {
      padding: 32px 0 88px;
    }

    .banner-panel {
      min-height: 310px;
      display: grid;
      place-items: center;
      text-align: center;
      border-radius: 46px;
      color: #fff;
      padding: 36px;
      background:
        radial-gradient(circle at 18% 25%, rgba(255,255,255,0.4), transparent 18%),
        radial-gradient(circle at 82% 35%, rgba(255,255,255,0.22), transparent 22%),
        linear-gradient(115deg, #7638fa, #ef2bad 54%, #ff7a00);
      box-shadow: 0 28px 82px rgba(118, 56, 250, 0.28);
      overflow: hidden;
      position: relative;
    }

    .banner-panel::before,
    .banner-panel::after {
      content: "";
      position: absolute;
      width: 180px;
      height: 180px;
      border-radius: 48px;
      border: 2px solid rgba(255,255,255,0.36);
      transform: rotate(18deg);
    }

    .banner-panel::before { left: -55px; top: -42px; }
    .banner-panel::after { right: -45px; bottom: -70px; }

    .banner h2 {
      position: relative;
      z-index: 1;
      margin: 0;
      max-width: 860px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(2.5rem, 7vw, 6.7rem);
      line-height: 0.95;
      letter-spacing: -0.08em;
    }

    .news-head {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 24px;
      margin-bottom: 24px;
    }

    .view-more {
      flex: 0 0 auto;
      font-weight: 900;
      color: var(--purple);
      padding: 11px 0;
    }

    .carousel-wrap { position: relative; }

    .news-carousel {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(290px, 390px);
      gap: 18px;
      overflow-x: auto;
      overscroll-behavior-inline: contain;
      scroll-snap-type: inline mandatory;
      scroll-padding-inline: max(20px, calc((100vw - var(--max)) / 2));
      padding: 4px max(20px, calc((100vw - var(--max)) / 2)) 28px;
      margin-inline: calc(max(20px, calc((100vw - var(--max)) / 2)) * -1);
      -webkit-overflow-scrolling: touch;
      scrollbar-width: thin;
      scrollbar-color: rgba(118, 56, 250, 0.55) rgba(118, 56, 250, 0.08);
    }

    .news-carousel::-webkit-scrollbar { height: 10px; }
    .news-carousel::-webkit-scrollbar-track { background: rgba(118, 56, 250, 0.08); border-radius: 999px; }
    .news-carousel::-webkit-scrollbar-thumb { background: linear-gradient(90deg, var(--purple), var(--magenta), var(--orange)); border-radius: 999px; }

    .news-card {
      scroll-snap-align: start;
      min-height: 478px;
      border-radius: 30px;
      background: #fff;
      border: 1px solid rgba(14, 10, 22, 0.08);
      box-shadow: 0 18px 48px rgba(37, 20, 68, 0.1);
      overflow: hidden;
      transition: transform 180ms ease, box-shadow 180ms ease;
    }

    .news-card:hover {
      transform: translateY(-5px);
      box-shadow: 0 26px 62px rgba(37, 20, 68, 0.16);
    }

    .thumb {
      height: 210px;
      position: relative;
      overflow: hidden;
      background: var(--thumb-bg);
    }

    .thumb::before {
      content: "";
      position: absolute;
      inset: 22px;
      border-radius: 28px;
      background: rgba(255, 255, 255, 0.25);
      border: 1px solid rgba(255, 255, 255, 0.36);
      transform: rotate(var(--tilt));
    }

    .thumb::after {
      content: attr(data-icon);
      position: absolute;
      inset: 0;
      display: grid;
      place-items: center;
      font-size: 4.4rem;
      filter: drop-shadow(0 14px 24px rgba(0,0,0,0.14));
    }

    .news-body { padding: 22px; }

    .tags {
      display: flex;
      flex-wrap: wrap;
      gap: 7px;
      min-height: 31px;
      margin-bottom: 18px;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      min-height: 28px;
      padding: 0 9px;
      border-radius: 999px;
      background: #f2ecff;
      color: #5b22cd;
      font-size: 0.72rem;
      font-weight: 900;
      letter-spacing: 0.035em;
    }

    .news-card h3 {
      margin: 0;
      color: #100d17;
      font-size: clamp(1.18rem, 2vw, 1.55rem);
      line-height: 1.16;
      letter-spacing: -0.04em;
    }

    .date {
      margin: 22px 0 0;
      color: var(--muted);
      font-weight: 800;
      font-size: 0.93rem;
    }

    .carousel-controls {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      margin-top: 2px;
    }

    .scroll-btn {
      width: 48px;
      height: 48px;
      border: 1px solid var(--line);
      border-radius: 16px;
      background: #fff;
      color: var(--black);
      font-size: 1.35rem;
      font-weight: 900;
      cursor: pointer;
      box-shadow: 0 12px 28px rgba(37, 20, 68, 0.08);
    }

    .download { padding: 72px 0 84px; }

    .download-card {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      border-radius: 38px;
      padding: clamp(28px, 5vw, 54px);
      background:
        radial-gradient(circle at 92% 10%, rgba(255, 122, 0, 0.18), transparent 23%),
        #101015;
      color: white;
    }

    .download h2 {
      margin: 0 0 8px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(2.2rem, 5vw, 5rem);
      line-height: 0.98;
      letter-spacing: -0.07em;
    }

    .download p {
      margin: 0;
      color: rgba(255,255,255,0.72);
      font-size: 1.15rem;
      font-weight: 800;
    }

    .store-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
    }

    .store-btn {
      min-width: 150px;
      min-height: 54px;
      padding: 0 18px;
      color: #111;
      background: #fff;
    }

    .store-btn.alt {
      color: #fff;
      background: linear-gradient(100deg, var(--purple), var(--magenta));
    }

    .footer {
      padding: 58px 0 32px;
      background: #f7f4fb;
      border-top: 1px solid rgba(14, 10, 22, 0.08);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.3fr repeat(5, minmax(120px, 1fr));
      gap: 30px;
    }

    .footer-brand p {
      max-width: 270px;
      margin: 15px 0 0;
      color: var(--muted);
      line-height: 1.6;
      font-weight: 600;
    }

    .footer-col h3 {
      margin: 0 0 14px;
      font-size: 0.86rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .footer-col ul {
      list-style: none;
      margin: 0;
      padding: 0;
      display: grid;
      gap: 10px;
    }

    .footer-col a {
      color: #56505f;
      font-size: 0.94rem;
      font-weight: 700;
    }

    .footer-col a:hover { color: var(--purple); }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 22px;
      flex-wrap: wrap;
      margin-top: 48px;
      padding-top: 24px;
      border-top: 1px solid rgba(14, 10, 22, 0.1);
      color: #56505f;
      font-weight: 700;
      font-size: 0.91rem;
    }

    .language {
      border: 1px solid var(--line);
      background: #fff;
      border-radius: 999px;
      padding: 10px 13px;
      font: inherit;
      color: var(--ink);
    }

    .socials,
    .legal {
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 10px;
    }

    .socials a {
      width: 34px;
      height: 34px;
      display: grid;
      place-items: center;
      border-radius: 12px;
      background: #fff;
      border: 1px solid rgba(14, 10, 22, 0.08);
      font-weight: 900;
      font-size: 0.76rem;
    }

    .legal a { color: #56505f; }
    .legal a:hover { color: var(--purple); }

    @media (max-width: 980px) {
      .desktop-links { display: none; }
      .menu-toggle { display: inline-block; }
      .hero-grid,
      .feature-card,
      .split-grid {
        grid-template-columns: 1fr;
      }
      .hero { padding-top: 48px; }
      .hero-visual { min-height: 510px; }
      .split-card { min-height: 470px; }
      .footer-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
      .footer-brand { grid-column: 1 / -1; }
      .download-card { align-items: flex-start; flex-direction: column; }
    }

    @media (max-width: 680px) {
      .site-shell { width: min(100% - 28px, var(--max)); }
      .nav { min-height: 68px; }
      .brand { font-size: 1.12rem; }
      .brand-mark { width: 34px; height: 34px; border-radius: 12px; }
      .login-btn { display: none; }
      .hero { padding: 38px 0 36px; }
      .hero h1 { font-size: clamp(3rem, 16vw, 4.8rem); }
      .hero-visual { min-height: 430px; border-radius: 32px; }
      .phone-card { width: 230px; height: 398px; border-radius: 36px; }
      .phone-feed { height: 232px; }
      .reaction-float { right: 12px; top: 45px; }
      .creator-float { left: 12px; bottom: 78px; }
      .safety-float { right: 14px; bottom: 20px; }
      .section-pad { padding: 48px 0; }
      .feature-card,
      .split-card,
      .download-card { border-radius: 28px; }
      .feature-mosaic { grid-template-columns: 1fr; transform: none; }
      .mini-tile { min-height: 112px; }
      .card-graphic { left: 20px; right: 20px; height: 118px; }
      .badge-bubble { width: 58px; height: 58px; border-radius: 20px; font-size: 1.65rem; }
      .banner { padding-bottom: 56px; }
      .banner-panel { min-height: 250px; border-radius: 30px; }
      .news-head { align-items: flex-start; flex-direction: column; }
      .news-carousel {
        grid-auto-columns: minmax(282px, 86vw);
        gap: 14px;
      }
      .news-card { min-height: 450px; }
      .thumb { height: 185px; }
      .carousel-controls { display: none; }
      .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 26px 18px; }
      .footer-bottom { align-items: flex-start; flex-direction: column; }
    }

    @media (max-width: 430px) {
      .footer-grid { grid-template-columns: 1fr; }
      .store-actions, .store-btn, .primary-btn { width: 100%; }
      .primary-btn, .store-btn { justify-content: center; }
      .split-card { min-height: 510px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
      }
    }
  </style>
</head>
