  <script>
    const menuButton = document.querySelector('.menu-toggle');
    const mobileMenu = document.querySelector('#mobile-menu');
    const mobileLinks = document.querySelectorAll('.mobile-links a');
    const carousel = document.querySelector('#news-carousel');
    const scrollButtons = document.querySelectorAll('[data-scroll]');

    function closeMenu() {
      menuButton.setAttribute('aria-expanded', 'false');
      menuButton.setAttribute('aria-label', 'Open navigation menu');
      mobileMenu.classList.remove('is-open');
    }

    menuButton.addEventListener('click', () => {
      const isOpen = menuButton.getAttribute('aria-expanded') === 'true';
      menuButton.setAttribute('aria-expanded', String(!isOpen));
      menuButton.setAttribute('aria-label', isOpen ? 'Open navigation menu' : 'Close navigation menu');
      mobileMenu.classList.toggle('is-open', !isOpen);
    });

    mobileLinks.forEach((link) => link.addEventListener('click', closeMenu));

    scrollButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const direction = button.dataset.scroll === 'next' ? 1 : -1;
        carousel.scrollBy({ left: direction * Math.min(430, carousel.clientWidth * 0.86), behavior: 'smooth' });
      });
    });

    carousel.addEventListener('keydown', (event) => {
      if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return;
      event.preventDefault();
      carousel.scrollBy({ left: (event.key === 'ArrowRight' ? 1 : -1) * 360, behavior: 'smooth' });
    });
  </script>
